import ast,hashlib,json,pathlib,subprocess
root=pathlib.Path('/workspace'); p=json.loads((root/'proposal.json').read_text()); r=json.loads(subprocess.check_output(['python3',str(root/'tools.py'),'resolve','run://r-001'],text=True))
def validate(x,s,path='study'):
 t=s.get('type'); kinds={'object':dict,'array':list,'string':str,'boolean':bool}
 if t in kinds: assert isinstance(x,kinds[t]), (path,t)
 if 'enum' in s: assert x in s['enum'],path
 if 'const' in s: assert x==s['const'],path
 if isinstance(x,dict):
  assert all(k in x for k in s.get('required',[])),path
  if s.get('additionalProperties') is False: assert set(x)<=set(s.get('properties',{})),path
  for k,v in x.items():
   if k in s.get('properties',{}): validate(v,s['properties'][k],path+'.'+k)
 if isinstance(x,list):
  assert len(x)>=s.get('minItems',0),path
  for i,v in enumerate(x): validate(v,s.get('items',{}),path+str(i))
 if isinstance(x,str): assert len(x)>=s.get('minLength',0),path
validate(p['study'],r['study_schema']); assert p['study']['protocol_ref']==r['required_study_protocol_ref']; assert p['parent_trial'] in r['context']['allowed_observation_ids']; assert set(p['study']['evidence_refs'])<=set(r['context']['allowed_observation_ids'])
assert 1<=len(p['variants'])<=4; assert len({v['name'] for v in p['variants']})==len(p['variants']); assert any(v['role']=='candidate' for v in p['variants'])
trees=[]
for v in p['variants']:
 assert pathlib.Path(v['file']).name==v['file'] and v['file'].endswith('.py'); assert v['role'] in ['candidate','control']
 source=(root/v['file']).read_text(); compile(source,v['file'],'exec'); tree=ast.parse(source)
 config=next(n for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets))
 assert ast.literal_eval(config.value)==v['config']; tree.body.remove(config); trees.append(ast.dump(tree,include_attributes=False))
 for n in ast.walk(tree):
  if isinstance(n,ast.Import): assert all(a.name.split('.')[0] in ['torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib','unirank','model_zoo'] for a in n.names)
  if isinstance(n,ast.ImportFrom): assert n.module.split('.')[0] in ['torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib','unirank','model_zoo']
 print('PASS syntax/config/imports',v['file'],'sha256',hashlib.sha256(source.encode()).hexdigest())
assert len(set(trees))==1
old=ast.parse((root/'history_g2_r0022_field_cyclic.py').read_text()); new=ast.parse((root/'candidate.py').read_text())
def methods(tree):
 return {c.name:{n.name:ast.dump(n,include_attributes=False) for n in c.body if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef))} for c in tree.body if isinstance(c,ast.ClassDef)}
o,n=methods(old),methods(new); changed=[]
for cls in o:
 assert set(o[cls])==set(n[cls])
 for method in o[cls]:
  if o[cls][method]"'!=n[cls][method]: changed.append(cls+'"'.'+method)
assert changed==['Model.__init__','Model._transport_values'],changed
assert hashlib.sha256((root/'baseline_reference.py').read_bytes()).hexdigest()=='f4b473cbacf60d72cff90f3721ad754dd617ee6065fe3fca2fc9cd4be2b25c36'
print('PASS proposal schema, authorized local references, standalone source parity, unchanged baseline')
print('Only changed methods:',changed)
PY"

